import React, { useState } from 'react';

const SearchFilter = ({ onSearch }) => {
  const [filters, setFilters] = useState({
    min_budget: '',
    max_budget: '',
    min_bedrooms: '',
    max_distance: '',
    furnish_status: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validFilters = {};
    
    // Only include filters with values
    Object.keys(filters).forEach(key => {
      if (filters[key]) {
        validFilters[key] = filters[key];
      }
    });
    
    onSearch(validFilters);
  };

  const handleReset = () => {
    setFilters({
      min_budget: '',
      max_budget: '',
      min_bedrooms: '',
      max_distance: '',
      furnish_status: ''
    });
    onSearch({});
  };

  return (
    <div className="bg-gray-100 p-4 rounded-lg mb-6">
      <h3 className="text-lg font-semibold mb-4">Filter Properties</h3>
      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Min Budget</label>
            <input
              type="number"
              name="min_budget"
              value={filters.min_budget}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded"
              placeholder="Min $"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Max Budget</label>
            <input
              type="number"
              name="max_budget"
              value={filters.max_budget}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded"
              placeholder="Max $"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Min Bedrooms</label>
            <input
              type="number"
              name="min_bedrooms"
              value={filters.min_bedrooms}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded"
              placeholder="Min Bedrooms"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Max Distance (miles)</label>
            <input
              type="number"
              name="max_distance"
              value={filters.max_distance}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded"
              placeholder="Max Distance"
              step="0.1"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Furnish Status</label>
            <select
              name="furnish_status"
              value={filters.furnish_status}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded"
            >
              <option value="">Any</option>
              <option value="Furnished">Furnished</option>
              <option value="Unfurnished">Unfurnished</option>
              <option value="Partially Furnished">Partially Furnished</option>
            </select>
          </div>
        </div>
        
        <div className="flex justify-end space-x-2">
          <button
            type="button"
            onClick={handleReset}
            className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300"
          >
            Reset
          </button>
          <button
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            Search
          </button>
        </div>
      </form>
    </div>
  );
};

export default SearchFilter;
